PRAGMA foreign_keys = ON;
CREATE TABLE projects (id TEXT PRIMARY KEY, title TEXT NOT NULL, aspect TEXT NOT NULL DEFAULT '16:9', status TEXT NOT NULL DEFAULT 'draft', approved_script_id TEXT, revision INTEGER NOT NULL DEFAULT 0, auto_episode INTEGER, music_key TEXT, created_at INTEGER NOT NULL);
CREATE TABLE script_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL, body TEXT NOT NULL, report_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE INDEX scripts_project ON script_versions(project_id,created_at);
CREATE TABLE assets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), ref TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, spec_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', approved_version INTEGER, UNIQUE(project_id,ref));
CREATE TABLE asset_versions (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), version INTEGER NOT NULL, files_json TEXT NOT NULL, instruction TEXT NOT NULL DEFAULT '', script_version_id TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(asset_id,version));
CREATE TABLE episodes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), number INTEGER NOT NULL, title TEXT NOT NULL, UNIQUE(project_id,number));
CREATE TABLE scenes (id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES episodes(id), number INTEGER NOT NULL, duration REAL NOT NULL, spec_json TEXT NOT NULL, content_hash TEXT NOT NULL, script_version_id TEXT NOT NULL, chain_group TEXT, approved_clip_id TEXT, UNIQUE(episode_id,number));
CREATE TABLE clips (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES scenes(id), take INTEGER NOT NULL, prompt TEXT NOT NULL DEFAULT '', params_json TEXT NOT NULL DEFAULT '{}', r2_key TEXT, qa_json TEXT, status TEXT NOT NULL DEFAULT 'queued', asset_versions_json TEXT NOT NULL, context_clip_id TEXT, script_version_id TEXT NOT NULL, owner_note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(scene_id,take));
CREATE TABLE jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', priority INTEGER NOT NULL DEFAULT 0, claimed_by TEXT, claimed_at INTEGER, claim_token TEXT, lease_until INTEGER, attempt INTEGER NOT NULL DEFAULT 0, error TEXT, result_json TEXT, pct REAL NOT NULL DEFAULT 0, stage TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX jobs_claim ON jobs(status,priority DESC,created_at);
CREATE UNIQUE INDEX active_fix ON jobs(project_id) WHERE type='fix_script' AND status IN ('queued','claimed','running');
CREATE TABLE renders (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), scope TEXT NOT NULL, r2_key TEXT, srt_r2_key TEXT, clip_ids_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', created_at INTEGER NOT NULL);
CREATE TABLE gpu_workers (id TEXT PRIMARY KEY, last_seen INTEGER NOT NULL, info_json TEXT NOT NULL);
